                int i = scanner.nextInt();
                int v = scanner.nextInt();
                int l = i;
                int r = Math.min(n, i + v - 1);
                long a = -1;
                long b = (long) v + i;

                bitA.add(l, a);
                bitA.add(r + 1, -a);
                bitB.add(l, b);
                bitB.add(r + 1, -b);
            } else if (type == 2) {
                int i = scanner.nextInt();
                int v = scanner.nextInt();
                int l = Math.max(1, i - v + 1);
                int r = i;
                long a = 1;
                long b = (long) v - i;

                bitA.add(l, a);
                bitA.add(r + 1, -a);
                bitB.add(l, b);
                bitB.add(r + 1, -b);
            } else if (type == 3) {
                int i = scanner.nextInt();
                long valA = bitA.query(i);
                long valB = bitB.query(i);
                long ans = valA * i + valB;
                sb.append(ans).append('\n');
            }
        }

        System.out.print(sb);
    }
}
