const fs = require('fs');

function main() {
    const buffer = fs.readFileSync(0);
    let offset = 0;

    function readInt() {
        while (offset < buffer.length && buffer[offset] <= 32) {
            offset++;
        }
        if (offset >= buffer.length) return null;
        let res = 0;
        while (offset < buffer.length && buffer[offset] > 32) {
            res = res * 10 + (buffer[offset] - 48);
            offset++;
        }
        return res;
    }

    const N = readInt();
    if (N === null) return;
    const M = readInt();

    // Como N <= 200,000 e os valores acumulados podem atingir até ~4e10,
    // Float64Array suporta inteiros de até 2^53 - 1 com precisão exata.
    const treeA = new Float64Array(N + 2);
    const treeB = new Float64Array(N + 2);

    function addA(idx, val) {
        for (; idx <= N + 1; idx += idx & -idx) {
            treeA[idx] += val;
        }
    }

    function addB(idx, val) {
        for (; idx <= N + 1; idx += idx & -idx) {
            treeB[idx] += val;
        }
    }

    function queryA(idx) {
        let sum = 0;
        for (; idx > 0; idx -= idx & -idx) {
            sum += treeA[idx];
        }
        return sum;
    }

    function queryB(idx) {
        let sum = 0;
        for (; idx > 0; idx -= idx & -idx) {
            sum += treeB[idx];
        }
        return sum;
    }

    let out = '';
    const CHUNK_SIZE = 65536;

    for (let k = 0; k < M; k++) {
        const type = readInt();
        if (type === 1) {
            const I = readInt();
            const V = readInt();
            const L = I;
            const R = I + V - 1 < N ? I + V - 1 : N;

            const aVal = V + I;
            const bVal = -1;

            addA(L, aVal);
            addA(R + 1, -aVal);

            addB(L, bVal);
            addB(R + 1, -bVal);
        } else if (type === 2) {
            const I = readInt();
            const V = readInt();
            const L = I - V + 1 > 1 ? I - V + 1 : 1;
            const R = I;

            const aVal = V - I;
            const bVal = 1;

            addA(L, aVal);
            addA(R + 1, -aVal);

            addB(L, bVal);
            addB(R + 1, -bVal);
        } else if (type === 3) {
            const I = readInt();
            const a = queryA(I);
            const b = queryB(I);
            const ans = a + b * I;
            out += ans + '\n';
            if (out.length >= CHUNK_SIZE) {
                process.stdout.write(out);
                out = '';
            }
        }
    }

    if (out.length > 0) {
        process.stdout.write(out);
    }
}

main();
